#include <cassert>
#include <cstdint>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
// Original teaching model, not Kid Icarus: Uprising's implementation.
class Attempt {
    std::int64_t wallet_;
    int stake_ = 0;
    bool active_ = false;
public:
    explicit Attempt(int wallet) : wallet_(wallet < 0 ? 0 : wallet) {}
    std::int64_t Wallet() const { return wallet_; }
    bool Active() const { return active_; }
    bool Begin(int stake) {
        if (active_ || stake < 0 || stake > 1000 || wallet_ < stake) return false;
        wallet_ -= stake; stake_ = stake; active_ = true; return true;
    }
    bool Settle(bool won) {
        if (!active_) return false;
        // Win returns escrow plus an equally sized reward; loss loses escrow.
        if (won) wallet_ += 2LL * stake_;
        stake_ = 0; active_ = false; return true;
    }
};
int main() {
    Attempt a(100);
    assert(!a.Settle(true));
    assert(!a.Begin(-1) && !a.Begin(1001) && !a.Begin(101));
    assert(a.Wallet() == 100 && !a.Active());
    assert(a.Begin(40) && a.Wallet() == 60);
    assert(!a.Begin(1) && a.Wallet() == 60);
    assert(a.Settle(true) && a.Wallet() == 140);
    assert(!a.Settle(true) && a.Wallet() == 140);
    assert(a.Begin(40) && a.Settle(false) && a.Wallet() == 100);
    assert(a.Begin(0) && a.Settle(false) && a.Wallet() == 100);
    Attempt empty(-5);
    assert(empty.Wallet() == 0 && !empty.Begin(1));
    for (int i=0;i<10000;++i) {
        assert(a.Begin(1) && a.Settle(true));
        assert(a.Begin(1) && a.Settle(false));
    }
    assert(a.Wallet() == 100 && !a.Active());
}
